import React from 'react';

const plans = [
  { name: 'Starter', price: '$999', description: 'For early-stage brands', features: ['Brand strategy', 'Landing page', 'Creative direction'] },
  { name: 'Scale', price: '$2,499', description: 'For growing businesses', features: ['Paid media setup', 'Creative testing', 'Analytics dashboard'], featured: true },
  { name: 'Authority', price: '$4,999', description: 'For brands ready to dominate', features: ['Full ad system', 'Multi-channel strategy', 'Weekly optimization'] },
];

function PricingPage({ user, onLogout }) {
  return (
    <div style={{ minHeight: '100vh', background: '#0b1120', color: '#fff', padding: '32px 20px' }}>
      <div style={{ maxWidth: '1200px', margin: '0 auto' }}>
        <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '32px' }}>
          <div style={{ fontSize: '1.5rem', fontWeight: 700 }}>Motion Franzy</div>
          <div style={{ display: 'flex', gap: '12px', alignItems: 'center' }}>
            {user ? (
              <>
                <span>{user.email}</span>
                {user.role === 'admin' && <a href="/admin" style={{ color: '#8bd3ff' }}>Admin</a>}
                <button onClick={onLogout} style={{ padding: '10px 16px', borderRadius: 10, border: '1px solid #334155', background: 'transparent', color: '#fff', cursor: 'pointer' }}>Logout</button>
              </>
            ) : (
              <a href="/login" style={{ padding: '10px 16px', borderRadius: 10, background: 'linear-gradient(135deg,#8b5cf6,#3b82f6)', color: '#fff', fontWeight: 700 }}>Login</a>
            )}
          </div>
        </header>

        <section style={{ textAlign: 'center', marginBottom: '48px' }}>
          <h1 style={{ fontSize: 'clamp(2.4rem, 6vw, 5rem)', marginBottom: '16px' }}>Creative systems that turn clicks into customers.</h1>
          <p style={{ maxWidth: '760px', margin: '0 auto', color: '#cbd5e1', fontSize: '1.1rem' }}>
            We build strategy, landing pages, and ad systems that help brands scale faster with less wasted spend.
          </p>
        </section>

        <section style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '20px' }}>
          {plans.map((plan) => (
            <div key={plan.name} style={{
              background: plan.featured ? 'linear-gradient(135deg, #8b5cf6, #3b82f6)' : '#111827',
              padding: '24px',
              borderRadius: '18px',
              border: '1px solid rgba(148,163,184,0.2)',
              boxShadow: plan.featured ? '0 18px 50px rgba(59,130,246,0.35)' : 'none'
            }}>
              <h3>{plan.name}</h3>
              <div style={{ fontSize: '2.2rem', fontWeight: 800 }}>{plan.price}</div>
              <p style={{ color: '#dbeafe' }}>{plan.description}</p>
              <ul style={{ listStyle: 'none', padding: 0, display: 'grid', gap: '10px', margin: '20px 0 0' }}>
                {plan.features.map((feature) => (
                  <li key={feature}>✓ {feature}</li>
                ))}
              </ul>
            </div>
          ))}
        </section>
      </div>
    </div>
  );
}

export default PricingPage;
